/****** Object:  StoredProcedure [dbo].[usp_AboutPage_Get]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- PublicSite: one call for About page
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) about page content
--   4) site contact information

CREATE   PROCEDURE [dbo].[usp_AboutPage_Get]
    @LanguageCode NVARCHAR(10) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. About page
    --------------------------------------------------------------------------
    SELECT
        menu.Url,
        tr.Name,
        tr.Slogan,
        tr.Body,
        a.ImageUrl,
        CASE
            WHEN a.ActivityStartDate IS NULL THEN NULL
            ELSE DATEDIFF(YEAR, a.ActivityStartDate, CAST(GETDATE() AS DATE))
                 - CASE
                       WHEN DATEADD(YEAR, DATEDIFF(YEAR, a.ActivityStartDate, CAST(GETDATE() AS DATE)), a.ActivityStartDate)
                            > CAST(GETDATE() AS DATE)
                       THEN 1
                       ELSE 0
                   END
        END AS ExperienceYears,
        tr.SeoTitle,
        tr.MetaDescription,
        tr.MetaRobots,
        tr.OgTitle,
        tr.OgDescription,
        tr.OgImage,
        tr.OgType,
        tr.OgUrl
    FROM dbo.About AS a
    INNER JOIN dbo.MenuItems AS menu
        ON menu.Id = a.MenuItemId
    INNER JOIN dbo.AboutTranslations AS tr
        ON tr.AboutId = a.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE a.IsActive = 1
      AND menu.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode;

    --------------------------------------------------------------------------
    -- 4. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
