CREATE   PROCEDURE [dbo].[usp_BlogImages_Insert]
    @FileName    NVARCHAR(200),
    @ContentType NVARCHAR(100),
    @Content     VARBINARY(MAX),
    @Id          INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF @FileName IS NULL OR LTRIM(RTRIM(@FileName)) = N''
    BEGIN
        THROW 50051, N'Image file name is required.', 1;
    END

    IF @ContentType IS NULL OR LTRIM(RTRIM(@ContentType)) = N''
    BEGIN
        THROW 50052, N'Image content type is required.', 1;
    END

    IF @Content IS NULL OR DATALENGTH(@Content) = 0
    BEGIN
        THROW 50053, N'Image content is required.', 1;
    END

    IF EXISTS (SELECT 1 FROM dbo.BlogImages WHERE FileName = @FileName)
    BEGIN
        THROW 50054, N'An image with this file name already exists.', 1;
    END

    INSERT INTO dbo.BlogImages (FileName, ContentType, Content)
    VALUES (@FileName, @ContentType, @Content);

    SET @Id = CAST(SCOPE_IDENTITY() AS INT);
END
GO
/****** Object:  StoredProcedure [dbo].[usp_BlogPage_Get]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PublicSite: one call for blog listing page
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) paging (TotalCount, PageNumber, PageSize)
--   4) published blog posts for the requested page
--   5) site contact information
-- @LanguageCode: optional, default language when NULL/empty
-- @PageNumber: 1-based page index
-- @PageSize: posts per page (1..50, default 6)

CREATE   PROCEDURE [dbo].[usp_BlogPage_Get]
    @LanguageCode NVARCHAR(10) = NULL,
    @PageNumber   INT = 1,
    @PageSize     INT = 6
AS
BEGIN
    SET NOCOUNT ON;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    IF @PageSize IS NULL OR @PageSize < 1
        SET @PageSize = 6;
    IF @PageSize > 50
        SET @PageSize = 50;
    IF @PageNumber IS NULL OR @PageNumber < 1
        SET @PageNumber = 1;

    DECLARE @TotalCount INT;

    SELECT @TotalCount = COUNT(1)
    FROM dbo.BlogPosts AS bp
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = bp.LanguageId
    WHERE bp.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
      AND bp.PublishedAt IS NOT NULL
      AND bp.PublishedAt <= SYSUTCDATETIME();

    DECLARE @PageCount INT =
        CASE
            WHEN @TotalCount = 0 THEN 1
            ELSE CEILING(@TotalCount * 1.0 / @PageSize)
        END;

    IF @PageNumber > @PageCount
        SET @PageNumber = @PageCount;

    DECLARE @Offset INT = (@PageNumber - 1) * @PageSize;

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. Paging
    --------------------------------------------------------------------------
    SELECT
        @TotalCount AS TotalCount,
        @PageNumber AS PageNumber,
        @PageSize AS PageSize;

    --------------------------------------------------------------------------
    -- 4. Published blog posts (page)
    --------------------------------------------------------------------------
    SELECT
        bp.Url,
        bp.ImageUrl,
        bp.Name,
        bp.MetaDescription
    FROM dbo.BlogPosts AS bp
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = bp.LanguageId
    WHERE bp.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
      AND bp.PublishedAt IS NOT NULL
      AND bp.PublishedAt <= SYSUTCDATETIME()
    ORDER BY bp.SortOrder, bp.PublishedAt DESC, bp.Id
    OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY;

    --------------------------------------------------------------------------
    -- 5. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_BlogPostPage_Get]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PublicSite: one call for a single blog article page
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) latest published posts for the sidebar (excluding the current article)
--   4) selected published article
--   5) site contact information
-- @LanguageCode: optional, default language when NULL/empty
-- @BlogPostUrl: article url, e.g. /blog/finding-investors-meeting

CREATE   PROCEDURE [dbo].[usp_BlogPostPage_Get]
    @LanguageCode NVARCHAR(10)  = NULL,
    @BlogPostUrl  NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    IF @BlogPostUrl IS NULL OR LTRIM(RTRIM(@BlogPostUrl)) = N''
    BEGIN
        THROW 50040, N'Blog post url is required.', 1;
    END

    SET @BlogPostUrl = LTRIM(RTRIM(@BlogPostUrl));
    IF LEFT(@BlogPostUrl, 1) <> N'/'
    BEGIN
        SET @BlogPostUrl = N'/' + @BlogPostUrl;
    END

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. Latest articles (sidebar)
    --------------------------------------------------------------------------
    SELECT TOP (5)
        bp.Url,
        bp.ImageUrl,
        bp.Name,
        bp.MetaDescription
    FROM dbo.BlogPosts AS bp
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = bp.LanguageId
    WHERE bp.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
      AND bp.PublishedAt IS NOT NULL
      AND bp.PublishedAt <= SYSUTCDATETIME()
      AND bp.Url <> @BlogPostUrl
    ORDER BY bp.PublishedAt DESC, bp.Id DESC;

    --------------------------------------------------------------------------
    -- 4. Selected article
    --------------------------------------------------------------------------
    SELECT
        bp.Url,
        bp.ImageUrl,
        bp.Name,
        bp.Body,
        bp.SeoTitle,
        bp.MetaDescription,
        bp.MetaRobots,
        bp.OgTitle,
        bp.OgDescription,
        bp.OgImage,
        bp.OgType,
        bp.OgUrl
    FROM dbo.BlogPosts AS bp
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = bp.LanguageId
    WHERE bp.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
      AND bp.Url = @BlogPostUrl
      AND bp.PublishedAt IS NOT NULL
      AND bp.PublishedAt <= SYSUTCDATETIME();

    --------------------------------------------------------------------------
    -- 5. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
