/****** Object:  StoredProcedure [dbo].[usp_BlogPosts_GetFeatured]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PublicSite home: up to 3 blog cards
-- Featured posts first (PublishedAt DESC), then newest non-featured to fill to 3

CREATE   PROCEDURE [dbo].[usp_BlogPosts_GetFeatured]
    @LanguageCode NVARCHAR(10) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @LanguageId TINYINT;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageId = Id
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SELECT TOP (1) @LanguageId = Id
        FROM dbo.Languages
        WHERE IsActive = 1
          AND Code = LTRIM(RTRIM(@LanguageCode));
    END

    IF @LanguageId IS NULL
    BEGIN
        SELECT TOP (1) @LanguageId = Id
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END

    IF @LanguageId IS NULL
    BEGIN
        SELECT
            CAST(NULL AS NVARCHAR(500)) AS Url,
            CAST(NULL AS NVARCHAR(500)) AS ImageUrl,
            CAST(NULL AS NVARCHAR(200)) AS Name
        WHERE 1 = 0;
        RETURN;
    END

    ;WITH Visible AS (
        SELECT
            Url,
            ImageUrl,
            Name,
            IsFeatured,
            PublishedAt,
            Id
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
          AND IsActive = 1
          AND PublishedAt IS NOT NULL
          AND PublishedAt <= SYSUTCDATETIME()
    ),
    Ranked AS (
        SELECT
            Url,
            ImageUrl,
            Name,
            CASE WHEN IsFeatured = 1 THEN 0 ELSE 1 END AS Bucket,
            ROW_NUMBER() OVER (
                PARTITION BY CASE WHEN IsFeatured = 1 THEN 0 ELSE 1 END
                ORDER BY PublishedAt DESC, Id DESC
            ) AS Rn
        FROM Visible
    )
    SELECT TOP (3)
        Url,
        ImageUrl,
        Name
    FROM Ranked
    WHERE Rn <= 3
    ORDER BY Bucket, Rn;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_BlogPosts_Insert]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PublicSite / admin: insert a blog article
-- @Url: slug or full path. Stored as /blog/{slug}
-- @SortOrder: omit to append at the end. If the number is already used in the language,
-- every SortOrder in that language is rebuilt.
-- @PublishedAt: omit or pass a date to publish; pass NULL with @IsPublished = 0 for a draft
-- @Id: new identity

CREATE   PROCEDURE [dbo].[usp_BlogPosts_Insert]
    @LanguageId       TINYINT,
    @Url              NVARCHAR(500),
    @Name             NVARCHAR(200),
    @Body             NVARCHAR(MAX) = NULL,
    @ImageUrl         NVARCHAR(500) = NULL,
    @PublishedAt      DATETIME2(0) = NULL,
    @IsPublished      BIT = 1,
    @SortOrder        INT = NULL,
    @IsActive         BIT = 1,
    @SeoTitle         NVARCHAR(200) = NULL,
    @MetaDescription  NVARCHAR(500) = NULL,
    @MetaRobots       NVARCHAR(100) = NULL,
    @OgTitle          NVARCHAR(200) = NULL,
    @OgDescription    NVARCHAR(500) = NULL,
    @OgImage          NVARCHAR(500) = NULL,
    @OgType           NVARCHAR(50) = NULL,
    @OgUrl            NVARCHAR(500) = NULL,
    @IsFeatured       BIT = 0,
    @Id               INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    IF @Name IS NULL OR LTRIM(RTRIM(@Name)) = N''
    BEGIN
        THROW 50041, N'Blog post name is required.', 1;
    END

    IF @Url IS NULL OR LTRIM(RTRIM(@Url)) = N''
    BEGIN
        THROW 50044, N'Blog post url is required.', 1;
    END

    IF NOT EXISTS (SELECT 1 FROM dbo.Languages WHERE Id = @LanguageId)
    BEGIN
        THROW 50042, N'Language was not found.', 1;
    END

    SET @Name = LTRIM(RTRIM(@Name));
    SET @Url = LOWER(LTRIM(RTRIM(@Url)));
    SET @Url = REPLACE(@Url, N'\', N'/');

    WHILE @Url LIKE N'%//'
        SET @Url = REPLACE(@Url, N'//', N'/');

    IF LEFT(@Url, 1) <> N'/'
        SET @Url = N'/' + @Url;

    IF @Url NOT LIKE N'/blog/%'
    BEGIN
        IF @Url = N'/blog'
        BEGIN
            THROW 50044, N'Blog post url is required.', 1;
        END

        SET @Url = N'/blog' + CASE WHEN LEFT(@Url, 1) = N'/' THEN @Url ELSE N'/' + @Url END;
    END

    IF EXISTS (
        SELECT 1
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
          AND Url = @Url
    )
    BEGIN
        THROW 50043, N'A blog post with this url already exists for the language.', 1;
    END

    IF @SortOrder IS NULL
    BEGIN
        SELECT @SortOrder = ISNULL(MAX(SortOrder), 0) + 1
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId;
    END
    ELSE IF @SortOrder < 1
        SET @SortOrder = 1;

    DECLARE @SortOrderCollision BIT = 0;
    IF EXISTS (
        SELECT 1
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
          AND SortOrder = @SortOrder
    )
        SET @SortOrderCollision = 1;

    IF @MetaRobots IS NULL OR LTRIM(RTRIM(@MetaRobots)) = N''
        SET @MetaRobots = N'index, follow';

    IF @OgType IS NULL OR LTRIM(RTRIM(@OgType)) = N''
        SET @OgType = N'article';

    IF @SeoTitle IS NULL OR LTRIM(RTRIM(@SeoTitle)) = N''
        SET @SeoTitle = @Name;

    IF @OgTitle IS NULL OR LTRIM(RTRIM(@OgTitle)) = N''
        SET @OgTitle = @Name;

    IF @OgUrl IS NULL OR LTRIM(RTRIM(@OgUrl)) = N''
        SET @OgUrl = @Url;

    IF @IsPublished = 1
        SET @PublishedAt = ISNULL(@PublishedAt, SYSUTCDATETIME());
    ELSE
        SET @PublishedAt = NULL;

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO dbo.BlogPosts
        (
            LanguageId,
            Url,
            ImageUrl,
            Name,
            Body,
            PublishedAt,
            SortOrder,
            IsActive,
            SeoTitle,
            MetaDescription,
            MetaRobots,
            OgTitle,
            OgDescription,
            OgImage,
            OgType,
            OgUrl,
            IsFeatured
        )
        VALUES
        (
            @LanguageId,
            @Url,
            NULLIF(LTRIM(RTRIM(@ImageUrl)), N''),
            @Name,
            @Body,
            @PublishedAt,
            @SortOrder,
            ISNULL(@IsActive, 1),
            @SeoTitle,
            NULLIF(LTRIM(RTRIM(@MetaDescription)), N''),
            @MetaRobots,
            @OgTitle,
            NULLIF(LTRIM(RTRIM(@OgDescription)), N''),
            NULLIF(LTRIM(RTRIM(@OgImage)), N''),
            @OgType,
            @OgUrl,
            ISNULL(@IsFeatured, 0)
        );

        SET @Id = CAST(SCOPE_IDENTITY() AS INT);

        IF @SortOrderCollision = 1
            EXEC dbo.usp_BlogPosts_ResequenceSortOrder
                @LanguageId = @LanguageId,
                @Id = @Id,
                @SortOrder = @SortOrder,
                @PlaceFirst = 1;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_BlogPosts_ResequenceSortOrder]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Admin: rebuild SortOrder for every blog post in a language.
-- @Id takes @SortOrder. @PlaceFirst = 1 puts it before any post that already
-- had that number; 0 puts it after (used when moving an existing post down).

CREATE   PROCEDURE [dbo].[usp_BlogPosts_ResequenceSortOrder]
    @LanguageId TINYINT,
    @Id         INT,
    @SortOrder  INT,
    @PlaceFirst BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    IF @SortOrder < 1
        SET @SortOrder = 1;

    ;WITH numbered AS
    (
        SELECT
            Id,
            ROW_NUMBER() OVER (
                ORDER BY
                    CASE WHEN Id = @Id THEN @SortOrder ELSE SortOrder END,
                    CASE
                        WHEN Id = @Id THEN CASE WHEN @PlaceFirst = 1 THEN 0 ELSE 1 END
                        ELSE CASE WHEN @PlaceFirst = 1 THEN 1 ELSE 0 END
                    END,
                    Id
            ) AS NewSortOrder
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
    )
    UPDATE bp
    SET SortOrder = numbered.NewSortOrder
    FROM dbo.BlogPosts AS bp
    INNER JOIN numbered ON numbered.Id = bp.Id;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_BlogPosts_Update]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Admin: update a blog article
-- @ImageUrl: omit or pass NULL to keep the current cover
-- @SortOrder: omit or pass NULL to keep the current order.
-- If the number is already used in the language, every SortOrder in that language is rebuilt.
-- @PublishedAt: omit or pass a date to publish; pass NULL with @IsPublished = 0 for a draft

CREATE   PROCEDURE [dbo].[usp_BlogPosts_Update]
    @Id               INT,
    @LanguageId       TINYINT,
    @Url              NVARCHAR(500),
    @Name             NVARCHAR(200),
    @Body             NVARCHAR(MAX) = NULL,
    @ImageUrl         NVARCHAR(500) = NULL,
    @PublishedAt      DATETIME2(0) = NULL,
    @IsPublished      BIT = 1,
    @SortOrder        INT = NULL,
    @IsActive         BIT = 1,
    @SeoTitle         NVARCHAR(200) = NULL,
    @MetaDescription  NVARCHAR(500) = NULL,
    @MetaRobots       NVARCHAR(100) = NULL,
    @OgTitle          NVARCHAR(200) = NULL,
    @OgDescription    NVARCHAR(500) = NULL,
    @OgImage          NVARCHAR(500) = NULL,
    @OgType           NVARCHAR(50) = NULL,
    @OgUrl            NVARCHAR(500) = NULL,
    @IsFeatured       BIT = 0
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM dbo.BlogPosts WHERE Id = @Id)
    BEGIN
        THROW 50045, N'Blog post was not found.', 1;
    END

    IF @Name IS NULL OR LTRIM(RTRIM(@Name)) = N''
    BEGIN
        THROW 50041, N'Blog post name is required.', 1;
    END

    IF @Url IS NULL OR LTRIM(RTRIM(@Url)) = N''
    BEGIN
        THROW 50044, N'Blog post url is required.', 1;
    END

    IF NOT EXISTS (SELECT 1 FROM dbo.Languages WHERE Id = @LanguageId)
    BEGIN
        THROW 50042, N'Language was not found.', 1;
    END

    SET @Name = LTRIM(RTRIM(@Name));
    SET @Url = LOWER(LTRIM(RTRIM(@Url)));
    SET @Url = REPLACE(@Url, N'\', N'/');

    WHILE @Url LIKE N'%//'
        SET @Url = REPLACE(@Url, N'//', N'/');

    IF LEFT(@Url, 1) <> N'/'
        SET @Url = N'/' + @Url;

    IF @Url NOT LIKE N'/blog/%'
    BEGIN
        IF @Url = N'/blog'
        BEGIN
            THROW 50044, N'Blog post url is required.', 1;
        END

        SET @Url = N'/blog' + CASE WHEN LEFT(@Url, 1) = N'/' THEN @Url ELSE N'/' + @Url END;
    END

    IF EXISTS (
        SELECT 1
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
          AND Url = @Url
          AND Id <> @Id
    )
    BEGIN
        THROW 50043, N'A blog post with this url already exists for the language.', 1;
    END

    IF @MetaRobots IS NULL OR LTRIM(RTRIM(@MetaRobots)) = N''
        SET @MetaRobots = N'index, follow';

    IF @OgType IS NULL OR LTRIM(RTRIM(@OgType)) = N''
        SET @OgType = N'article';

    IF @SeoTitle IS NULL OR LTRIM(RTRIM(@SeoTitle)) = N''
        SET @SeoTitle = @Name;

    IF @OgTitle IS NULL OR LTRIM(RTRIM(@OgTitle)) = N''
        SET @OgTitle = @Name;

    IF @OgUrl IS NULL OR LTRIM(RTRIM(@OgUrl)) = N''
        SET @OgUrl = @Url;

    IF @IsPublished = 1
        SET @PublishedAt = ISNULL(@PublishedAt, SYSUTCDATETIME());
    ELSE
        SET @PublishedAt = NULL;

    DECLARE @CurrentLanguageId TINYINT;
    DECLARE @CurrentSortOrder INT;
    SELECT
        @CurrentLanguageId = LanguageId,
        @CurrentSortOrder = SortOrder
    FROM dbo.BlogPosts
    WHERE Id = @Id;

    DECLARE @NewSortOrder INT = ISNULL(@SortOrder, @CurrentSortOrder);
    IF @NewSortOrder < 1
        SET @NewSortOrder = 1;

    DECLARE @SortOrderCollision BIT = 0;
    IF EXISTS (
        SELECT 1
        FROM dbo.BlogPosts
        WHERE LanguageId = @LanguageId
          AND SortOrder = @NewSortOrder
          AND Id <> @Id
    )
        SET @SortOrderCollision = 1;

    DECLARE @PlaceFirst BIT = 1;
    IF @CurrentLanguageId = @LanguageId AND @NewSortOrder > @CurrentSortOrder
        SET @PlaceFirst = 0;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.BlogPosts
        SET
            LanguageId = @LanguageId,
            Url = @Url,
            ImageUrl = COALESCE(NULLIF(LTRIM(RTRIM(@ImageUrl)), N''), ImageUrl),
            Name = @Name,
            Body = @Body,
            PublishedAt = @PublishedAt,
            SortOrder = @NewSortOrder,
            IsActive = ISNULL(@IsActive, 1),
            SeoTitle = @SeoTitle,
            MetaDescription = NULLIF(LTRIM(RTRIM(@MetaDescription)), N''),
            MetaRobots = @MetaRobots,
            OgTitle = @OgTitle,
            OgDescription = NULLIF(LTRIM(RTRIM(@OgDescription)), N''),
            OgImage = NULLIF(LTRIM(RTRIM(@OgImage)), N''),
            OgType = @OgType,
            OgUrl = @OgUrl,
            IsFeatured = ISNULL(@IsFeatured, 0)
        WHERE Id = @Id;

        IF @SortOrderCollision = 1
            EXEC dbo.usp_BlogPosts_ResequenceSortOrder
                @LanguageId = @LanguageId,
                @Id = @Id,
                @SortOrder = @NewSortOrder,
                @PlaceFirst = @PlaceFirst;

        IF @CurrentLanguageId <> @LanguageId
            EXEC dbo.usp_BlogPosts_ResequenceSortOrder
                @LanguageId = @CurrentLanguageId,
                @Id = @Id,
                @SortOrder = 2147483647,
                @PlaceFirst = 0;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO
/****** Object:  StoredProcedure [dbo].[usp_HomePage_Get]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
================================================================================
  Adds IconUrl to usp_HomePage_Get and usp_PracticeAreaPage_Get
================================================================================
*/

-- PublicSite: one call for Home page
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) home page content (hero, strip banner, SEO)
--   4) home feature cards
--   5) practice area links
--   6) featured blog cards (usp_BlogPosts_GetFeatured)
--   7) site contact information
-- @LanguageCode: optional, default language when NULL/empty

CREATE   PROCEDURE [dbo].[usp_HomePage_Get]
    @LanguageCode NVARCHAR(10) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. Home page
    --------------------------------------------------------------------------
    SELECT
        tr.HeroEyebrow,
        tr.HeroTitle,
        tr.PageText,
        tr.HeroCtaText,
        h.HeroCtaUrl,
        h.HeroVideoUrl,
        tr.StripBannerText,
        tr.SeoTitle,
        tr.MetaDescription,
        tr.MetaRobots,
        tr.OgTitle,
        tr.OgDescription,
        tr.OgImage,
        tr.OgType,
        tr.OgUrl
    FROM dbo.Home AS h
    INNER JOIN dbo.MenuItems AS menu
        ON menu.Id = h.MenuItemId
    INNER JOIN dbo.HomeTranslations AS tr
        ON tr.HomeId = h.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE h.IsActive = 1
      AND menu.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode;

    --------------------------------------------------------------------------
    -- 4. Home features
    --------------------------------------------------------------------------
    SELECT
        f.ImageUrl,
        tr.Text,
        f.SortOrder
    FROM dbo.HomeFeatures AS f
    INNER JOIN dbo.HomeFeatureTranslations AS tr
        ON tr.HomeFeatureId = f.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE f.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
    ORDER BY f.SortOrder, f.Id;

    --------------------------------------------------------------------------
    -- 5. Practice area links
    --------------------------------------------------------------------------
    SELECT
        menu.Url,
        tr.Name,
        tr.Summary,
        pa.ImageUrl,
        pa.IconUrl,
        pa.SortOrder
    FROM dbo.PracticeAreas AS pa
    INNER JOIN dbo.MenuItems AS menu
        ON menu.Id = pa.MenuItemId
    INNER JOIN dbo.PracticeAreaTranslations AS tr
        ON tr.PracticeAreaId = pa.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE pa.IsActive = 1
      AND menu.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
    ORDER BY pa.SortOrder, menu.Url;

    --------------------------------------------------------------------------
    -- 6. Featured blog cards
    --------------------------------------------------------------------------
    EXEC dbo.usp_BlogPosts_GetFeatured @LanguageCode = @LanguageCode;

    --------------------------------------------------------------------------
    -- 7. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
