/****** Object:  StoredProcedure [dbo].[usp_Languages_Insert]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[usp_Languages_Insert]
    @Code       NVARCHAR(10),
    @Name       NVARCHAR(100),
    @NativeName NVARCHAR(100),
    @IsRtl      BIT,
    @IsDefault  BIT,
    @IsActive   BIT,
    @SortOrder  INT,
    @Id         TINYINT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    IF @IsDefault = 1
    BEGIN
        UPDATE dbo.Languages
        SET IsDefault = 0
        WHERE IsDefault = 1;
    END

    INSERT INTO dbo.Languages
    (
        Code,
        Name,
        NativeName,
        IsRtl,
        IsDefault,
        IsActive,
        SortOrder
    )
    VALUES
    (
        @Code,
        @Name,
        @NativeName,
        @IsRtl,
        @IsDefault,
        @IsActive,
        @SortOrder
    );

    SET @Id = CAST(SCOPE_IDENTITY() AS TINYINT);

    COMMIT TRANSACTION;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_Languages_Update]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[usp_Languages_Update]
    @Id         TINYINT,
    @Code       NVARCHAR(10),
    @Name       NVARCHAR(100),
    @NativeName NVARCHAR(100),
    @IsRtl      BIT,
    @IsDefault  BIT,
    @IsActive   BIT,
    @SortOrder  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION;

    IF @IsDefault = 1
    BEGIN
        UPDATE dbo.Languages
        SET IsDefault = 0
        WHERE IsDefault = 1
          AND Id <> @Id;
    END

    UPDATE dbo.Languages
    SET
        Code = @Code,
        Name = @Name,
        NativeName = @NativeName,
        IsRtl = @IsRtl,
        IsDefault = @IsDefault,
        IsActive = @IsActive,
        SortOrder = @SortOrder
    WHERE Id = @Id;

    COMMIT TRANSACTION;
END
GO
