-- PublicSite: one call for Practice Area page
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) all active practice area sections (for page links)
--   4) selected practice area page content
--   5) site contact information
-- @LanguageCode: optional, default language when NULL/empty
-- @PracticeAreaUrl: menu url of the section, e.g. /hi-tech

CREATE   PROCEDURE [dbo].[usp_PracticeAreaPage_Get]
    @LanguageCode     NVARCHAR(10)  = NULL,
    @PracticeAreaUrl  NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;

    IF @PracticeAreaUrl IS NULL OR LTRIM(RTRIM(@PracticeAreaUrl)) = N''
    BEGIN
        THROW 50020, N'Practice area url is required.', 1;
    END

    SET @PracticeAreaUrl = LTRIM(RTRIM(@PracticeAreaUrl));
    IF LEFT(@PracticeAreaUrl, 1) <> N'/'
    BEGIN
        SET @PracticeAreaUrl = N'/' + @PracticeAreaUrl;
    END

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. All practice area sections (links)
    --------------------------------------------------------------------------
    SELECT
        menu.Url,
        tr.Name,
        tr.Summary,
        pa.ImageUrl,
        pa.IconUrl,
        pa.SortOrder
    FROM dbo.PracticeAreas AS pa
    INNER JOIN dbo.MenuItems AS menu
        ON menu.Id = pa.MenuItemId
    INNER JOIN dbo.PracticeAreaTranslations AS tr
        ON tr.PracticeAreaId = pa.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE pa.IsActive = 1
      AND menu.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
    ORDER BY pa.SortOrder, menu.Url;

    --------------------------------------------------------------------------
    -- 4. Selected practice area page
    --------------------------------------------------------------------------
    SELECT
        menu.Url,
        tr.Name,
        tr.Body,
        pa.ImageUrl,
        pa.IconUrl,
        tr.SeoTitle,
        tr.MetaDescription,
        tr.MetaRobots,
        tr.OgTitle,
        tr.OgDescription,
        tr.OgImage,
        tr.OgType,
        tr.OgUrl
    FROM dbo.PracticeAreas AS pa
    INNER JOIN dbo.MenuItems AS menu
        ON menu.Id = pa.MenuItemId
    INNER JOIN dbo.PracticeAreaTranslations AS tr
        ON tr.PracticeAreaId = pa.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE pa.IsActive = 1
      AND menu.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode
      AND menu.Url = @PracticeAreaUrl;

    --------------------------------------------------------------------------
    -- 5. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
