-- PublicSite: one call for Privacy Policy page
-- Body placeholders resolved here (not stored resolved):
--   <phone-number>  ContactInfo.Phone
--   <e-mail>        ContactInfo.Email
--   <date-update>   current date (dd/mm/yyyy)
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) privacy policy page content
--   4) site contact information
-- @LanguageCode: optional, default language when NULL/empty

CREATE   PROCEDURE [dbo].[usp_PrivacyPolicyPage_Get]
    @LanguageCode NVARCHAR(10) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    DECLARE @Phone NVARCHAR(50);
    DECLARE @Email NVARCHAR(256);

    SELECT TOP (1)
        @Phone = Phone,
        @Email = Email
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. Privacy policy page
    --------------------------------------------------------------------------
    SELECT
        p.Url,
        tr.Name,
        CASE
            WHEN tr.Body IS NULL THEN NULL
            ELSE REPLACE(
                    REPLACE(
                        REPLACE(tr.Body, N'<phone-number>', ISNULL(@Phone, N'')),
                        N'<e-mail>', ISNULL(@Email, N'')),
                    N'<date-update>', CONVERT(NVARCHAR(10), CAST(GETDATE() AS DATE), 103))
        END AS Body,
        tr.SeoTitle,
        tr.MetaDescription,
        tr.MetaRobots,
        tr.OgTitle,
        tr.OgDescription,
        tr.OgImage,
        tr.OgType,
        tr.OgUrl
    FROM dbo.PrivacyPolicy AS p
    INNER JOIN dbo.PrivacyPolicyTranslations AS tr
        ON tr.PrivacyPolicyId = p.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE p.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode;

    --------------------------------------------------------------------------
    -- 4. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
/****** Object:  StoredProcedure [dbo].[usp_TermsOfUsePage_Get]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PublicSite: one call for Terms of Use page
-- Body placeholders resolved here (not stored resolved):
--   <e-mail>           ContactInfo.Email
--   <date-update>      current date (dd/mm/yyyy)
--   <privacy-policy>   PrivacyPolicy.Url
-- Result sets:
--   1) active languages
--   2) active menu for language (Id/ParentId for tree)
--   3) terms of use page content
--   4) site contact information
-- @LanguageCode: optional, default language when NULL/empty

CREATE   PROCEDURE [dbo].[usp_TermsOfUsePage_Get]
    @LanguageCode NVARCHAR(10) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF @LanguageCode IS NULL OR LTRIM(RTRIM(@LanguageCode)) = N''
    BEGIN
        SELECT TOP (1) @LanguageCode = Code
        FROM dbo.Languages
        WHERE IsActive = 1
          AND IsDefault = 1
        ORDER BY SortOrder, Code;
    END
    ELSE
    BEGIN
        SET @LanguageCode = LTRIM(RTRIM(@LanguageCode));
    END

    DECLARE @Email NVARCHAR(256);
    DECLARE @PrivacyPolicyUrl NVARCHAR(500);

    SELECT TOP (1)
        @Email = Email
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;

    SELECT TOP (1)
        @PrivacyPolicyUrl = Url
    FROM dbo.PrivacyPolicy
    WHERE IsActive = 1
    ORDER BY Id;

    --------------------------------------------------------------------------
    -- 1. Languages
    --------------------------------------------------------------------------
    SELECT
        Code,
        NativeName,
        IsRtl,
        IsDefault,
        SortOrder
    FROM dbo.Languages
    WHERE IsActive = 1
    ORDER BY SortOrder, Code;

    --------------------------------------------------------------------------
    -- 2. Menu
    --------------------------------------------------------------------------
    SELECT
        m.Id,
        m.ParentId,
        m.Url,
        m.SortOrder,
        t.Title
    FROM dbo.MenuItems AS m
    INNER JOIN dbo.MenuItemTranslations AS t
        ON t.MenuItemId = m.Id
    INNER JOIN dbo.Languages AS l
        ON l.Id = t.LanguageId
    LEFT JOIN dbo.MenuItems AS parent
        ON parent.Id = m.ParentId
    WHERE m.IsActive = 1
      AND l.IsActive = 1
      AND l.Code = @LanguageCode
      AND (m.ParentId IS NULL OR parent.IsActive = 1)
    ORDER BY
        CASE WHEN m.ParentId IS NULL THEN m.SortOrder ELSE parent.SortOrder END,
        CASE WHEN m.ParentId IS NULL THEN 0 ELSE 1 END,
        m.SortOrder,
        m.Id;

    --------------------------------------------------------------------------
    -- 3. Terms of use page
    --------------------------------------------------------------------------
    SELECT
        p.Url,
        tr.Name,
        CASE
            WHEN tr.Body IS NULL THEN NULL
            ELSE REPLACE(
                    REPLACE(
                        REPLACE(tr.Body, N'<e-mail>', ISNULL(@Email, N'')),
                        N'<date-update>', CONVERT(NVARCHAR(10), CAST(GETDATE() AS DATE), 103)),
                    N'<privacy-policy>', ISNULL(@PrivacyPolicyUrl, N''))
        END AS Body,
        tr.SeoTitle,
        tr.MetaDescription,
        tr.MetaRobots,
        tr.OgTitle,
        tr.OgDescription,
        tr.OgImage,
        tr.OgType,
        tr.OgUrl
    FROM dbo.TermsOfUse AS p
    INNER JOIN dbo.TermsOfUseTranslations AS tr
        ON tr.TermsOfUseId = p.Id
    INNER JOIN dbo.Languages AS lang
        ON lang.Id = tr.LanguageId
    WHERE p.IsActive = 1
      AND lang.IsActive = 1
      AND lang.Code = @LanguageCode;

    --------------------------------------------------------------------------
    -- 4. Contact information
    --------------------------------------------------------------------------
    SELECT TOP (1)
        Email,
        Phone,
        WhatsApp
    FROM dbo.ContactInfo
    WHERE Email IS NOT NULL
       OR Phone IS NOT NULL
       OR WhatsApp IS NOT NULL
    ORDER BY Id;
END
GO
/****** Object:  Trigger [dbo].[TR_MenuItems_TwoLevelsOnly]    Script Date: 15/09/2026 17:20:17 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   TRIGGER [dbo].[TR_MenuItems_TwoLevelsOnly]
ON [dbo].[MenuItems]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM inserted i
        INNER JOIN dbo.MenuItems parent ON parent.Id = i.ParentId
        WHERE parent.ParentId IS NOT NULL
    )
    BEGIN
        THROW 50010, N'Menu supports only two levels: a child item cannot have a parent that is itself a child.', 1;
    END

    IF EXISTS
    (
        SELECT 1
        FROM inserted i
        WHERE i.ParentId IS NOT NULL
          AND EXISTS
          (
              SELECT 1
              FROM dbo.MenuItems child
              WHERE child.ParentId = i.Id
          )
    )
    BEGIN
        THROW 50011, N'Menu supports only two levels: an item that has children cannot become a child itself.', 1;
    END
END
GO
ALTER TABLE [dbo].[MenuItems] ENABLE TRIGGER [TR_MenuItems_TwoLevelsOnly]
GO